        assert_eq!(
            render_toon(&opts).unwrap(),
            "t[1]{a}:\n  aaaaaaaaa…\ntruncated[1]{row,field,removed}:\n  0,a,41\ntotalCount: 5\nhelp[1]: h"
        );

