    fn ac027b_serialization_error_reports_reason_and_first_failing_index() {
        let result = list("t", &[FailsToSerialize]);
        assert_eq!(result, Err(ToonError::InvalidItem { row_index: 0, reason: "boom".to_string() }));
    }

