//! Basic TOON list rendering example.
//! Run with: `cargo run -p michi-core --example basic_toon`

// Examples exist to print their output — the disallowed_macros ban on
// println! is scoped to library code, not demonstration binaries.
#![allow(clippy::disallowed_macros)]

use michi_core::toon::{render_toon, ToonOptions, Value};

fn main() {
    let opts = ToonOptions::new(
        "issues",
        vec!["number".to_string(), "title".to_string(), "state".to_string()],
        vec![
            vec![Value::Int(51815), Value::from("[Bug]: Telegram plugin"), Value::from("open")],
            vec![Value::Int(51812), Value::from("dark mode request"), Value::from("open")],
            vec![Value::Int(51800), Value::from("update dependencies, bump major"), Value::from("closed")],
        ],
    )
    .total_count(Some(8771))
    .hints(vec![
        "Run `gh-axi issue view <number>` to view an issue".to_string(),
        "Run `gh-axi issue list --state=open` to filter".to_string(),
    ]);

    let output = render_toon(&opts).expect("example input is valid");
    println!("{output}");
}
use michi_core::toon::{render_toon, ToonOptions, Value};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let opts = ToonOptions::new(
        "issues",
        vec!["number".to_string(), "title".to_string(), "state".to_string()],
        vec![
            vec![Value::Int(51815), Value::from("[Bug]: Telegram plugin"), Value::from("open")],
            vec![Value::Int(51812), Value::from("dark mode request"), Value::from("open")],
        ],
    )
    .total_count(Some(8771))
    .hints(vec!["Run `gh-axi issue view <number>` to view an issue".to_string()]);

    print!("{}", render_toon(&opts)?);
    Ok(())
}
use divan::Bencher;
use michi_core::toon::{render_toon, ToonOptions, Value};

fn main() {
    divan::main();
}

fn make_opts(n: usize) -> ToonOptions {
    ToonOptions::new(
        "issue",
        vec!["number".into(), "title".into(), "state".into()],
        (0..n)
            .map(|i| vec![Value::Int(i as i64), Value::from(format!("Issue title number {i}")), Value::from("open")])
            .collect(),
    )
    .total_count(Some(1000))
    .hints(vec!["Call get_issue with number=<number>".to_string()])
}

#[divan::bench(args = [1, 10, 100, 1000])]
fn render_n_rows(b: Bencher, n: usize) {
    let opts = make_opts(n);
    b.bench(|| render_toon(&opts).unwrap());
}

#[divan::bench]
fn render_with_comma_escaping(b: Bencher) {
    let opts = ToonOptions::new(
        "item",
        vec!["name".into()],
        (0..100).map(|i| vec![Value::from(format!("Item {i}, with comma"))]).collect(),
    );
    b.bench(|| render_toon(&opts).unwrap());
}
    let a = RetryConfig::new(3, Duration::from_millis(500), Duration::from_secs(30), 0.2);
    assert_eq!(a, RetryConfig::default());
    assert_ne!(a, RetryConfig::new(4, Duration::from_millis(500), Duration::from_secs(30), 0.2));
}

#[test]
fn toon_options_compare_by_value() {
    let build = || ToonOptions::new("issues", vec!["n".into()], vec![vec![Value::Int(1)]]).total_count(Some(1));
    assert_eq!(build(), build());
    assert_ne!(build(), build().total_count(Some(2)));
}

