import assert from 'node:assert/strict'
import {
  CallToolResultSchema,
  TextContentSchema,
  AnnotationsSchema,
  LATEST_PROTOCOL_VERSION,
} from '@modelcontextprotocol/sdk/types.js'
import {
  AgentResponse,
  emptyState,
  emptyStateWithHints,
  renderDomainError,
  renderStatus,
  renderPipeline,
  renderPartialSuccess,
