        if cell_count(sparse.len(), fields.len()) > MAX_CELLS {
            return Err(ToonError::TooManyCells { rows: sparse.len(), fields: fields.len(), max: MAX_CELLS });
        }
    }
    let rows: Vec<Vec<Value>> = sparse
        .into_iter()
